diffs.diff:
@@ -0,0 +1,24 @@
+.list { border-top: 1px solid var(--thorp-line-strong); }
+.heading { display: flex; align-items: end; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 20px 0; }
+.kicker { margin: 0 0 4px; color: var(--thorp-accent-soft); font: 600 .67rem/1.4 var(--thorp-font-display); letter-spacing: .14em; }
+.heading h2 { margin: 0; font-size: 1.3rem; }
+.cases { list-style: none; margin: 0; padding: 0; }
+.case { display: grid; grid-template-columns: minmax(120px, .33fr) minmax(0, 1fr); gap: 12px 28px; border-top: 1px solid var(--thorp-line); padding: 20px 0 24px; }
+.caseHeading { display: flex; align-items: baseline; gap: 12px; }
+.caseHeading h3 { margin: 0; font: 600 1.2rem/1.3 var(--thorp-font-body); }
+.months { grid-column: 2; margin: 0; color: var(--thorp-copy); font-size: .8rem; }
+.months span { margin-left: 8px; color: var(--thorp-foreground); }
+.reasons { grid-column: 2; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; }
+.reasons h4 { margin: 0 0 8px; color: var(--thorp-copy); font-size: .76rem; font-weight: 600; }
+.reasons ul { margin: 0; padding-left: 17px; color: var(--thorp-foreground); font-size: .84rem; line-height: 1.6; }
+.reasons li + li { margin-top: 4px; }
+.more { display: block; width: 100%; min-height: 44px; border: 1px solid var(--thorp-line-strong); margin-top: 12px; background: var(--thorp-surface); color: var(--thorp-foreground); cursor: pointer; }
+.more:hover { border-color: var(--thorp-accent-soft); }
+.more:focus-visible { outline: var(--thorp-focus-outline-compact); outline-offset: var(--thorp-focus-offset-compact); }
+.more:disabled { cursor: wait; opacity: .6; }
+.limitNote { margin: 14px 0 0; color: var(--thorp-copy); font-size: .78rem; }
+@media (max-width: 640px) {
+  .case { grid-template-columns: 1fr; gap: 10px; }
+  .months, .reasons { grid-column: 1; }
+  .reasons { grid-template-columns: 1fr; gap: 14px; }
+}

@@ -0,0 +1,10 @@
+.disclosure { display: grid; grid-template-columns: minmax(92px, auto) minmax(0, 1fr); align-items: baseline; gap: 8px 16px; border-left: 2px solid var(--thorp-line-strong); padding: 10px 14px; color: var(--thorp-copy); background: var(--thorp-surface); font-size: .82rem; line-height: 1.6; overflow-wrap: anywhere; }
+.disclosure strong { color: var(--thorp-foreground); font-weight: 600; }
+.disclosure p { margin: 0; }
+.disclosure p + p { margin-top: 5px; }
+.disclosure:focus-visible { outline: var(--thorp-focus-outline-compact); outline-offset: var(--thorp-focus-offset-compact); }
+.warning { border-left-color: var(--thorp-warning); }
+.warning strong { color: var(--thorp-warning); }
+.error { border-left-color: var(--thorp-negative); }
+.error strong { color: var(--thorp-negative); }
+@media (max-width: 520px) { .disclosure { grid-template-columns: 1fr; } }

@@ -0,0 +1,2 @@
+.empty { border-top: 1px solid var(--thorp-line-strong); padding: 24px 0 40px; }
+.empty h2 { margin: 0; color: var(--thorp-foreground); font-size: 1.2rem; line-height: 1.5; }

@@ -0,0 +1,5 @@
+.error { border-left: 2px solid var(--thorp-negative); padding: 18px 20px; background: var(--thorp-surface); }
+.error h2 { margin: 0 0 8px; color: var(--thorp-negative); font-size: 1.08rem; }
+.error p { margin: 0 0 16px; color: var(--thorp-copy); font-size: .84rem; }
+.error button { min-height: 42px; padding: 7px 14px; border: 1px solid var(--thorp-line-strong); color: var(--thorp-foreground); background: var(--thorp-surface-raised); cursor: pointer; }
+.error button:focus-visible { outline: var(--thorp-focus-outline-compact); outline-offset: var(--thorp-focus-offset-compact); }

@@ -0,0 +1,27 @@
+.page { min-height: 100svh; color: var(--thorp-foreground); background: var(--thorp-background); }
+.main { width: min(1320px, calc(100% - 80px)); margin: 0 auto; padding: 36px 0 80px; }
+.hero { border-bottom: 1px solid var(--thorp-line-strong); padding: 16px 0 32px; }
+.eyebrow { margin: 0; color: var(--thorp-accent-soft); font: 600 .68rem/1.4 var(--thorp-font-display); letter-spacing: .14em; }
+.hero h1 { margin: 10px 0; font: 600 clamp(2rem, 3vw, 2.7rem)/1.15 var(--thorp-font-body); letter-spacing: -.04em; }
+.hero > p:last-child { margin: 0; color: var(--thorp-copy); font-size: .88rem; }
+.searchForm { display: flex; align-items: end; flex-wrap: wrap; gap: 12px; padding: 26px 0; }
+.searchForm label { width: 100%; color: var(--thorp-copy); font-size: .8rem; }
+.searchForm select { min-width: min(100%, 280px); min-height: 46px; padding: 8px 12px; border: 1px solid var(--thorp-line-strong); border-radius: 5px; color: var(--thorp-foreground); background: var(--thorp-surface); font: inherit; }
+.searchForm button { min-height: 46px; padding: 8px 20px; border: 1px solid var(--thorp-accent); border-radius: 5px; color: var(--thorp-action-foreground); background: var(--thorp-accent); font: 600 .85rem/1.3 var(--thorp-font-body); cursor: pointer; }
+.searchForm button:disabled { opacity: .55; cursor: not-allowed; }
+.searchForm select:focus-visible, .searchForm button:focus-visible { outline: var(--thorp-focus-outline-compact); outline-offset: var(--thorp-focus-offset-compact); }
+.loading { margin: 24px 0; color: var(--thorp-copy); font-size: .85rem; }
+.results { min-width: 0; }
+.resultHeading { display: flex; justify-content: space-between; align-items: end; flex-wrap: wrap; gap: 12px; border-top: 1px solid var(--thorp-line-strong); padding: 22px 0; }
+.resultHeading h2 { margin: 4px 0 0; font-size: 1.5rem; }
+.resultHeading > p { margin: 0; color: var(--thorp-copy); font-size: .82rem; }
+.resultHeading strong { color: var(--thorp-foreground); font-variant-numeric: tabular-nums; }
+.disclosures { display: grid; gap: 8px; margin-bottom: 20px; }
+.dataAsOf { border-top: 1px solid var(--thorp-line); padding: 18px 0 24px; color: var(--thorp-copy); font-size: .78rem; line-height: 1.6; }
+.dataAsOf > p { margin: 0 0 8px; }
+.dataAsOf dl { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 0; }
+.dataAsOf dl > div { display: flex; flex-wrap: wrap; gap: 4px 8px; }
+.dataAsOf dt { color: var(--thorp-foreground); }
+.dataAsOf dd { margin: 0; }
+@media (max-width: 800px) { .main { width: calc(100% - 32px); padding-top: 18px; } }
+@media (max-width: 420px) { .main { width: calc(100% - 28px); } .searchForm select, .searchForm button { width: 100%; } }
